const registry = $('Load registry').first().json.registry;
const byId = Object.fromEntries(registry.intents.map((i) => [i.intent_id, i]));
const q = String(body.question || '');
const raw = $json || {};
const agentOut = typeof raw.output === 'string' && !('intents' in raw) ? raw.output : raw;
const parsed = raw.error ? { ok: false, value: {} } : parseAgentJson(agentOut, ['intents', 'confidence'], {});
const cls = parsed.value;
const ent = cls.entities && typeof cls.entities === 'object' ? cls.entities : {};
const pick = (re) => ((q.match(re) || [])[0] || '').toUpperCase() || null;
const slots = {
  record_id: ent.record_id || ent.ticket_id || pick(/\bC-\d{4}\b/i),
  booking_id: ent.booking_id || pick(/\bT\d{8}-\d{4}\b/i),
};
const intents = (Array.isArray(cls.intents) ? cls.intents : []).map(String).filter((i) => byId[i]);
const urgency = cls.urgency === 'high' ? 'high' : 'normal';
const base = {
  intents, slots, urgency, priority: urgency === 'high' ? 'high' : 'normal',
  category: intents[0] || 'unknown',
  confidence: typeof cls.confidence === 'number' ? cls.confidence : null,
  sentiment: cls.sentiment || '',
  used: ['ticketmoa-agents'],
  steps: { agents_ms: Date.now() - $('Load registry').first().json.t0 },
  t_routed: Date.now(),
  llm_calls: parsed.ok ? (typeof raw.llm_calls === 'number' ? raw.llm_calls : 1) : 0,
};
// 고객의 내부 운영 절차 요청은 공개 문서로 대신 답하지 않고 검색 전에 이관한다.
// 로그인·본인 확인은 제공하지 않으므로 제출된 이름은 직원 신원 증명이 아니다. 직원 절차는 공개 검색하지 않는다.
const staffProcedureRequested = /책임자\s*코드|수기\s*모드|(?:스태프|직원)\s*단말|staff-entry-manual/i.test(q)
  || /(?:스태프|직원|내부).{0,24}(?:수기.{0,12}(?:처리|절차|매뉴얼)|(?:입장|장애).{0,12}(?:처리\s*절차|매뉴얼)|전용.{0,12}(?:절차|매뉴얼))/i.test(q);
if (staffProcedureRequested) {
  return [{ json: { ...base, next: 'handoff', reason: 'staff_only_request', missing: [], escalate: false } }];
}
// 환불 2차 확인은 분류 없이 ticketmoa-refund로 보낸다 (Refund confirm?에서 바로 온다). 확정 여부는 refund 규칙이 판단한다.
const ctx = body.context && typeof body.context === 'object' ? body.context : {};
if (ctx.pending_action === 'refund_request' && typeof ctx.confirm === 'boolean') {
  const confirmSlots = { ...slots, booking_id: String(ctx.booking_id || '').toUpperCase() || slots.booking_id };
  return [{ json: { ...base, intents: ['refund_request'], slots: confirmSlots, category: 'refund_request', used: [], llm_calls: 0, next: 'refund', reason: '', missing: [], escalate: false } }];
}
if (!parsed.ok) {
  return [{ json: { ...base, next: 'handoff', reason: raw.error ? 'agents_failed' : 'agents_unreadable', agents_error: errText(raw.error), missing: [], escalate: false } }];
}
// 레지스트리 required_slots가 비어 있으면 missing에 더한다 (환불은 예매 번호도 인정)
const missing = (Array.isArray(cls.missing) ? cls.missing : []).map(String);
for (const id of intents) for (const s of byId[id].required_slots || []) {
  const have = s === 'record_id' ? slots.record_id || (id === 'refund_request' && slots.booking_id) : slots[s];
  if (!have && !missing.includes(s)) missing.push(s);
}
// 뜻이 분명해도 등록 업무가 없으면 일반 문서로 추측 답변하지 않고 이관한다. 모델 장애는 위 분기에서 별도 처리한다.
const d = decideRoute({ ...cls, intents, missing }, { attempt: Number(body.attempt) || 1 });
let next = d.next;
let reason = d.reason;
const hook = (id) => String(byId[id].handler || '').replace('/webhook/', '');
const hooks = intents.map(hook);
if (next === 'handler') {
  if (intents.some((i) => byId[i].automation === 'handoff')) { next = 'handoff'; reason = 'registry_handoff'; }
  else if (hooks.includes('ticketmoa-tech') && intents.includes('booking_lookup')) next = 'tech_lookup';
  else next = { 'ticketmoa-tech': 'tech', 'ticketmoa-refund': 'refund', 'ticketmoa-payment': 'payment' }[hooks[0]] || 'handoff';
}
// 근거를 찾아 함께 이관하는 경우: 당일 취소는 환불 규정 (TM-06), 강한 불만은 해당 업무 문서 (TM-05)
const signals = cls.signals && typeof cls.signals === 'object' ? cls.signals : {};
const angryScope = [...new Set(intents.flatMap((i) => byId[i].kb_scope || []))];
let evidence = null;
if (intents.includes('refund_request') && signals.show_day === true && next !== 'handoff') {
  next = 'evidence_handoff'; reason = 'show_day_cancel';
  evidence = { query: '관람 당일 취소 환불 규정 ', scope: ['refund-policy'], category: 'refund_exception', answer: '관람 당일 취소는 규정상 자동으로 처리하지 않아 상담원에게 넘깁니다.' };
} else if (reason === 'strong_negative_sentiment' && angryScope.length) {
  next = 'evidence_handoff';
